package wasmgc

import (
	"fmt"
	"os"
	"strings"
	"testing"
	"unicode"
)

// unicodeSource is std/unicode.howl as generated from the toolchain's
// unicode.CaseRanges, the table Go's unicode.ToLower and ToUpper use.
func unicodeSource() string {
	var b strings.Builder
	b.WriteString(`; Unicode case mapping for the WebAssembly backend's standard library:
; to_lower and to_upper as Go's strings.ToLower and ToUpper (unicode.ToLower
; and ToUpper per rune, invalid UTF-8 as U+FFFD).
;
; GENERATED by TestUnicodeTableIsCurrent from Go's unicode.CaseRanges
; (Unicode ` + unicode.Version + `); regenerate with
; HOWLFRAME_UPDATE=1 go test ./internal/backend/wasmgc -run TestUnicodeTableIsCurrent
(module
  ; table: the case ranges as lo, hi, upper delta, lower delta, in order of
  ; lo. A delta of 1114112 (MaxRune + 1) means the range alternates upper
  ; and lower case.
  (defun table ()
    (let (t (__hf_array ` + fmt.Sprint(4*len(unicode.CaseRanges)) + `) i 0)
      (do
        (for v (list`)
	for i, cr := range unicode.CaseRanges {
		if i%6 == 0 {
			b.WriteString("\n         ")
		}
		fmt.Fprintf(&b, " %d %d %d %d", cr.Lo, cr.Hi, cr.Delta[unicode.UpperCase], cr.Delta[unicode.LowerCase])
	}
	b.WriteString(`)
          (do (__hf_aset t i v) (set i (+ i 1))))
        (return t))))

  ; to: Go's unicode.to for rune r: the upper (which 0) or lower (which 1)
  ; case of r, or r when it has none.
  (defun to (t which r)
    (let (lo 0 hi (__hf_idiv (__hf_alen t) 4))
      (do
        (while (< lo hi)
          (let (m (__hf_idiv (+ lo hi) 2))
            (let (rlo (__hf_aget t (* m 4)) rhi (__hf_aget t (+ (* m 4) 1)))
              (cond
                ((and (<= rlo r) (<= r rhi))
                  (let (delta (__hf_aget t (+ (* m 4) (+ 2 which))))
                    (do
                      (if (> delta 1114111) (return (+ rlo (__hf_or (__hf_and (- r rlo) -2) which))))
                      (return (+ r delta)))))
                ((< r rlo) (set hi m))
                (else (set lo (+ m 1)))))))
        (return r))))

  ; map: s with every rune in the given case.
  (defun map (s which)
    (let (t (call table) n (__hf_byte_len s) i 0 parts (list))
      (do
        (while (< i n)
          (let (l (call __std_utf8_seq_len s i))
            (let (r (call __std_utf8_rune s i l))
              (do
                (if (< r 128)
                  (cond
                    ((and (= which 1) (and (>= r 65) (<= r 90))) (set r (+ r 32)))
                    ((and (= which 0) (and (>= r 97) (<= r 122))) (set r (- r 32))))
                  (set r (call to t which r)))
                (append parts (__hf_char r))
                (set i (+ i (if (= l 0) 1 l)))))))
        (return (str_join parts "")))))

  (export (defun lower (s) (return (call map s 1))))
  (export (defun upper (s) (return (call map s 0)))))
`)
	return b.String()
}

// TestUnicodeTableIsCurrent keeps std/unicode.howl in step with the
// generator. A toolchain with another Unicode version than the file's
// skips: the VM built with it maps case by that version too.
func TestUnicodeTableIsCurrent(t *testing.T) {
	const path = "std/unicode.howl"
	want := unicodeSource()
	if os.Getenv("HOWLFRAME_UPDATE") == "1" {
		if err := os.WriteFile(path, []byte(want), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	got, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(got), "(Unicode "+unicode.Version+")") {
		t.Skipf("std/unicode.howl was generated for another Unicode version than this toolchain's %s", unicode.Version)
	}
	if string(got) != want {
		t.Fatal("std/unicode.howl is out of date: HOWLFRAME_UPDATE=1 go test ./internal/backend/wasmgc -run TestUnicodeTableIsCurrent")
	}
}
